mapper.select:
SELECT
    COUNT(*)
FROM utb_app_mst
WHERE office_seq = #{officeSeq}
  AND app_seq = #{appSeq}
  AND del_yn = 'N'

mapper.delete:
DELETE FROM utb_app_mst
WHERE office_seq = #{officeSeq}
AND app_seq = #{appSeq}

mapper.update:
UPDATE utb_app_mst
SET del_yn = 'Y'
    , update_user = #{userSeq}
    , update_at = CURRENT_TIMESTAMP
WHERE office_seq = #{officeSeq}
AND app_seq = #{appSeq}
AND del_yn = 'N'
